def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    # Count opponent's defections and cooperations
    opp_def = 0
    opp_coop = 0
    my_def = 0
    my_coop = 0
    for i in range(n):
        mine, opp = history[i]
        if opp == 'D':
            opp_def += 1
        else:
            opp_coop += 1
        if mine == 'D':
            my_def += 1
        else:
            my_coop += 1
    # Detect if opponent is very cooperative
    if opp_coop == n:
        # If we never defected against them, cooperate; else exploit
        if my_def == 0:
            return 'C'
        else:
            return 'D'
    # Detect if opponent is always defecting
    if opp_def == n:
        return 'D'
    # Tit-for-tat with occasional forgiveness and retaliation
    last_mine, last_opp = history[-1]
    if last_opp == 'D':
        # Retaliate, but if we've been defecting a lot and they might be testing, sometimes cooperate
        if my_def > opp_def + 2 and opp_def < n // 2:
            return 'C'
        return 'D'
    else:
        # Opponent cooperated last round
        # If we've been defecting more than them, try to restore cooperation
        if my_def > opp_def:
            return 'C'
        # Otherwise cooperate
        return 'C'

